mapper.select:
select reg.name,com.merchandise_name as merchandiseName,com.merchandise_id as merchandiseId,der.`consume_ integral` as consumeIntegral, der.`logistics_odd`as logisticsOdd,der.`logistics_company` as logisticsCompany,der.`order_ status` as orderStatus,der.order_id as orderId, der.standby,der.add_date as addDate,der.user_code as userCode,der.order_number as orderNumber,ress.site,ress.detailed_site as detailedSite,ress.consignee_name as consigneeName, ress.consignee_phone as consigneePhone,ress.site_id as siteId from yh_user_order as der left join yh_user_reginfo as reg on der.user_code = reg.user_code inner join yh_user_commodity_data as com on der.merchandise_id = com.merchandise_id
and com.merchandise_type = #{merchandiseType}
and com.grouping_id = #{groupingId}
and com.merchandise_name like CONCAT('%',#{merchandiseName},'%')
inner join yh_user_shipping_address as ress on der.site_id = ress.site_id
and reg.name like CONCAT('%',#{name},'%')
and der.`order_ status` = #{orderStatus}
and der.add_date BETWEEN #{qtstrTime} AND #{qtendTime}
where com.org_code like CONCAT('%',#{orgCode},'%') order by der.add_date desc

select reg.name,com.merchandise_name as merchandiseName,com.merchandise_id as merchandiseId,der.`consume_ integral` as consumeIntegral, der.`logistics_odd`as logisticsOdd,der.`logistics_company` as logisticsCompany,der.`order_ status` as orderStatus,der.order_id as orderId, der.standby,der.add_date as addDate,der.user_code as userCode,der.order_number as orderNumber,ress.site,ress.detailed_site as detailedSite,ress.consignee_name as consigneeName, ress.consignee_phone as consigneePhone,ress.site_id as siteId from yh_user_order as der left join yh_user_reginfo as reg on der.user_code = reg.user_code inner join yh_user_commodity_data as com on der.merchandise_id = com.merchandise_id
and com.merchandise_type = #{merchandiseType}
and com.grouping_id = #{groupingId}
and com.merchandise_name = #{merchandiseName}
inner join yh_user_shipping_address as ress on der.site_id = ress.site_id
and reg.name like CONCAT('%',#{name},'%')
and der.`order_ status` = #{orderStatus}
and der.add_date BETWEEN #{qtstrTime} AND #{qtendTime}
left join yh_user_make_card as card on card.User_Code = reg.user_code LEFT JOIN yh_user_admin_info as yuai on yuai.id=card.doctor where yuai.user_code=#{orgCode} order by der.add_date desc
